// fleetwatch — pings every site in the bisks.net fleet and lights up a
// tile per site. The fleet list is a static snapshot (data/fleet.json,
// regenerated by sync-fleet.mjs from sites/*/site.json), and results live
// only in localStorage on your machine — no shared backend, no per-site
// state kept anywhere.
//
// As of 2026-09-09 the actual checking happens server-side, through this
// site's own Worker (/api/check, src/index.ts) — a Worker's fetch() isn't
// bound by browser CORS, so it can read the real status code back from
// another bisks.net subdomain. That's the gap this board launched with on
// 2026-09-07: back then a no-cors ping from the browser could only tell you
// the network round-tripped, so a 200 and a 404 looked identical. Now
// "down" means a real 4xx/5xx or a failed connection, not a guess.
//
// Sites are checked in batches (BATCH_SIZE per request, so the Worker's own
// subrequest count per call stays small) with a handful of batches in
// flight at once — not a coverage cap, every site in the fleet still gets
// checked, just a ceiling on concurrency so the tab and the Worker both
// stay responsive while ~600 checks run.
const BATCH_SIZE = 20;
const BATCH_CONCURRENCY = 6;
const LS_RESULTS = "fleetwatch.results.v2";
const AUTO_RESCAN_AFTER_MS = 60 * 60 * 1000; // an hour-old board auto-refreshes itself

const els = {
  summary: document.getElementById("summary"),
  scanBtn: document.getElementById("scanBtn"),
  troubleOnly: document.getElementById("troubleOnly"),
  progressTrack: document.getElementById("progressTrack"),
  progressFill: document.getElementById("progressFill"),
  grid: document.getElementById("grid"),
  lastScan: document.getElementById("lastScan"),
  shareBtn: document.getElementById("shareBtn"),
};

let SITES = [];
let results = {}; // name -> { status: "up"|"down"|"timeout"|"checking", at: epoch ms }
let scanning = false;
let lastScanAt = null;

function loadCache() {
  try {
    const raw = JSON.parse(localStorage.getItem(LS_RESULTS) || "null");
    if (raw && raw.results && raw.at) {
      results = raw.results;
      lastScanAt = raw.at;
    }
  } catch {
    results = {};
    lastScanAt = null;
  }
}

function saveCache() {
  localStorage.setItem(LS_RESULTS, JSON.stringify({ results, at: lastScanAt }));
}

function escapeHtml(s) {
  const d = document.createElement("div");
  d.textContent = s;
  return d.innerHTML;
}

function typeEmoji(type) {
  return { toy: "🧸", game: "🎮", tool: "🛠️", joke: "🃏", explainer: "📖", art: "🎨" }[type] || "✨";
}

function timeAgo(ms) {
  if (!ms) return "never scanned";
  const s = Math.round((Date.now() - ms) / 1000);
  if (s < 60) return "just now";
  const m = Math.round(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.round(m / 60);
  if (h < 48) return `${h}h ago`;
  return `${Math.round(h / 24)}d ago`;
}

function statusLabel(r) {
  if (r.status === "up") return r.code ? String(r.code) : "up";
  if (r.status === "down") return r.code ? String(r.code) : "down";
  return r.status;
}

function renderGrid() {
  const troubleOnly = els.troubleOnly.checked;
  els.grid.innerHTML = SITES.map((s) => {
    const r = results[s.name] || { status: "checking" };
    const hide = troubleOnly && (r.status === "up" || r.status === "checking") ? "hiddenByFilter" : "";
    return `<a class="tile ${r.status} ${hide}" href="${s.url}" target="_blank" rel="noopener" data-name="${escapeHtml(s.name)}">
      <div class="name"><span class="dot"></span>${escapeHtml(s.title)}</div>
      <div class="meta"><span>${typeEmoji(s.type)} ${s.type}</span><span>${statusLabel(r)}</span></div>
    </a>`;
  }).join("");
}

function updateTile(name) {
  const el = els.grid.querySelector(`.tile[data-name="${CSS.escape(name)}"]`);
  if (!el) return;
  const r = results[name];
  el.className = `tile ${r.status}`;
  const metaStatus = el.querySelector(".meta span:last-child");
  if (metaStatus) metaStatus.textContent = statusLabel(r);
  if (els.troubleOnly.checked && (r.status === "up" || r.status === "checking")) {
    el.classList.add("hiddenByFilter");
  }
}

function updateSummary(done, total) {
  const counts = { up: 0, down: 0, timeout: 0, checking: 0 };
  for (const s of SITES) {
    const r = results[s.name] || { status: "checking" };
    counts[r.status] = (counts[r.status] || 0) + 1;
  }
  els.progressFill.style.width = `${total ? (done / total) * 100 : 0}%`;
  els.summary.innerHTML = scanning
    ? `checking… <span class="up">${counts.up} up</span> · <span class="down">${counts.down} down</span> · <span class="timeout">${counts.timeout} timed out</span> · ${counts.checking} left of ${total}`
    : `<span class="up">${counts.up} up</span> · <span class="down">${counts.down} down</span> · <span class="timeout">${counts.timeout} timed out</span> of ${total} sites`;
  els.lastScan.textContent = `last full scan: ${timeAgo(lastScanAt)}`;
}

async function checkBatch(sites) {
  try {
    const res = await fetch("/api/check", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ urls: sites.map((s) => s.url) }),
    });
    if (!res.ok) throw new Error(`api/check ${res.status}`);
    const { results: rows } = await res.json();
    const byUrl = new Map(rows.map((r) => [r.url, r]));
    return sites.map((s) => {
      const r = byUrl.get(s.url);
      if (!r) return { name: s.name, status: "down" };
      if (r.ok) return { name: s.name, status: "up", code: r.status };
      if (r.timeout) return { name: s.name, status: "timeout" };
      return { name: s.name, status: "down", code: r.status || null };
    });
  } catch {
    // the check endpoint itself is unreachable (fleetwatch down, or the
    // visitor's own connection dropped) — don't claim the whole fleet is
    // down on the strength of that, just mark this batch unresolved.
    return sites.map((s) => ({ name: s.name, status: "down" }));
  }
}

async function runScan() {
  if (scanning) return;
  scanning = true;
  els.scanBtn.disabled = true;
  els.scanBtn.textContent = "scanning…";

  for (const s of SITES) results[s.name] = { status: "checking" };
  renderGrid();
  updateSummary(0, SITES.length);

  const batches = [];
  for (let i = 0; i < SITES.length; i += BATCH_SIZE) batches.push(SITES.slice(i, i + BATCH_SIZE));

  let done = 0;
  let cursor = 0;
  async function worker() {
    while (cursor < batches.length) {
      const batch = batches[cursor++];
      const rows = await checkBatch(batch);
      for (const r of rows) {
        results[r.name] = { status: r.status, code: r.code || null, at: Date.now() };
        done++;
        updateTile(r.name);
      }
      updateSummary(done, SITES.length);
    }
  }
  await Promise.all(Array.from({ length: Math.min(BATCH_CONCURRENCY, batches.length) }, worker));

  lastScanAt = Date.now();
  scanning = false;
  els.scanBtn.disabled = false;
  els.scanBtn.textContent = "rescan the fleet";
  saveCache();
  updateSummary(SITES.length, SITES.length);
}

function buildShareText() {
  const counts = { up: 0, down: 0, timeout: 0 };
  for (const s of SITES) {
    const r = results[s.name];
    if (r && counts[r.status] !== undefined) counts[r.status]++;
  }
  const trouble = SITES.length - counts.up;
  const url = "https://fleetwatch.bisks.net/";
  if (trouble === 0) {
    return `pinged all ${SITES.length} sites in the bisks.net fleet — everything's answering → ${url}`;
  }
  return `pinged all ${SITES.length} sites in the bisks.net fleet: ${counts.up} up, ${counts.down} down, ${counts.timeout} timed out → ${url}`;
}

async function init() {
  const res = await fetch("/data/fleet.json");
  const data = await res.json();
  SITES = data.sites;

  loadCache();
  renderGrid();
  updateSummary(Object.keys(results).length, SITES.length);

  els.scanBtn.addEventListener("click", runScan);
  els.troubleOnly.addEventListener("change", renderGrid);
  els.shareBtn.addEventListener("click", () => {
    window.open("https://bsky.app/intent/compose?text=" + encodeURIComponent(buildShareText()), "_blank", "noopener");
  });

  const stale = !lastScanAt || Date.now() - lastScanAt > AUTO_RESCAN_AFTER_MS;
  if (stale) runScan();
}

init();
